        }, {
          "url": "http://hl7.org/fhir/us/cqfmeasures/StructureDefinition/cqfm-logicDefinition",
          "extension": [ {
            "url": "libraryName",
            "valueString": "SupplementalDataElementsFHIR4"
          }, {
            "url": "name",
            "valueString": "SDE Sex"
          }, {
            "url": "statement",
            "valueString": "define \"SDE Sex\":\n  case\n      when Patient.gender = 'male' then Code { code: 'M', system: 'http://hl7.org/fhir/v3/AdministrativeGender', display: 'Male' }\n      when Patient.gender = 'female' then Code { code: 'F', system: 'http://hl7.org/fhir/v3/AdministrativeGender', display: 'Female' }\n      else null\n    end"
          }, {
            "url": "displaySequence",
            "valueInteger": 0
          } ]
        }, {
          "url": "http://hl7.org/fhir/us/cqfmeasures/StructureDefinition/cqfm-logicDefinition",
          "extension": [ {
            "url": "libraryName",
            "valueString": "ColorectalCancerScreeningsFHIR"
          }, {
            "url": "name",
            "valueString": "SDE Sex"
          }, {
            "url": "statement",
            "valueString": "define \"SDE Sex\":\n  SDE.\"SDE Sex\""
          }, {
            "url": "displaySequence",
            "valueInteger": 1
          } ]
        }, {
          "url": "http://hl7.org/fhir/us/cqfmeasures/StructureDefinition/cqfm-logicDefinition",
          "extension": [ {
            "url": "libraryName",
            "valueString": "ColorectalCancerScreeningsFHIR"
          }, {
            "url": "name",
            "valueString": "Colonoscopy Performed"
          }, {
            "url": "statement",
            "valueString": "define \"Colonoscopy Performed\":\n  [Procedure: \"Colonoscopy\"] Colonoscopy\n            where Colonoscopy.status = 'completed'\n              and Global.\"Normalize Interval\" ( Colonoscopy.performed ) ends 10 years or less on or before \n              end of \"Measurement Period\""
          }, {
            "url": "displaySequence",
            "valueInteger": 2
          } ]
        }, {
          "url": "http://hl7.org/fhir/us/cqfmeasures/StructureDefinition/cqfm-logicDefinition",
          "extension": [ {
            "url": "libraryName",
            "valueString": "ColorectalCancerScreeningsFHIR"
          }, {
            "url": "name",
            "valueString": "Fecal Occult Blood Test Performed"
          }, {
            "url": "statement",
            "valueString": "define \"Fecal Occult Blood Test Performed\":\n  [Observation: \"Fecal Occult Blood Test (FOBT)\"] FecalOccultResult\n            where FecalOccultResult.status in { 'final', 'amended', 'corrected' }\n              and exists ( FecalOccultResult.category FecalOccultResultCategory\n                  where \"laboratory\" in FHIRHelpers.ToConcept ( FecalOccultResultCategory ).codes\n              )\n              and FecalOccultResult.value is not null\n              and Global.\"Latest\" ( FecalOccultResult.effective ) during \"Measurement Period\""
          }, {
            "url": "displaySequence",
            "valueInteger": 3
          } ]
        }, {
          "url": "http://hl7.org/fhir/us/cqfmeasures/StructureDefinition/cqfm-logicDefinition",
          "extension": [ {
            "url": "libraryName",
            "valueString": "ColorectalCancerScreeningsFHIR"
          }, {
            "url": "name",
            "valueString": "Flexible Sigmoidoscopy Performed"
          }, {
            "url": "statement",
            "valueString": "define \"Flexible Sigmoidoscopy Performed\":\n  [Procedure: \"Flexible Sigmoidoscopy\"] FlexibleSigmoidoscopy\n            where FlexibleSigmoidoscopy.status = 'completed'\n              and Global.\"Normalize Interval\" ( FlexibleSigmoidoscopy.performed ) ends 5 years or less on or before \n              end of \"Measurement Period\""
          }, {
            "url": "displaySequence",
            "valueInteger": 4
          } ]
        }, {
          "url": "http://hl7.org/fhir/us/cqfmeasures/StructureDefinition/cqfm-logicDefinition",
          "extension": [ {
            "url": "libraryName",
            "valueString": "ColorectalCancerScreeningsFHIR"
          }, {
            "url": "name",
            "valueString": "Fecal Immunochemical Test DNA Performed"
          }, {
            "url": "statement",
            "valueString": "define \"Fecal Immunochemical Test DNA Performed\":\n  [Observation: \"FIT DNA\"] FitDNA\n            where FitDNA.status in { 'final', 'amended', 'corrected' }\n              and exists ( FitDNA.category FitDNACategory\n                  where \"laboratory\" in FHIRHelpers.ToConcept ( FitDNACategory ).codes\n              )\n              and FitDNA.value is not null\n              and Global.\"Latest\" ( FitDNA.effective ) 3 years or less on or before \n              end of \"Measurement Period\""
          }, {
            "url": "displaySequence",
            "valueInteger": 5
          } ]
        }, {
          "url": "http://hl7.org/fhir/us/cqfmeasures/StructureDefinition/cqfm-logicDefinition",
          "extension": [ {
            "url": "libraryName",
            "valueString": "ColorectalCancerScreeningsFHIR"
          }, {
            "url": "name",
            "valueString": "CT Colonography Performed"
          }, {
            "url": "statement",
            "valueString": "define \"CT Colonography Performed\":\n  [Observation: \"CT Colonography\"] Colonography\n            where Colonography.status in { 'final', 'amended', 'corrected', 'appended' }\n              and Global.\"Normalize Interval\" ( Colonography.effective ) ends 5 years or less on or before \n              end of \"Measurement Period\""
          }, {
            "url": "displaySequence",
            "valueInteger": 6
          } ]
        }, {
          "url": "http://hl7.org/fhir/us/cqfmeasures/StructureDefinition/cqfm-logicDefinition",
          "extension": [ {
            "url": "libraryName",
            "valueString": "ColorectalCancerScreeningsFHIR"
          }, {
            "url": "name",
            "valueString": "Numerator"
          }, {
            "url": "statement",
            "valueString": "define \"Numerator\":\n  exists \"Colonoscopy Performed\"\n            or exists \"Fecal Occult Blood Test Performed\"\n            or exists \"Flexible Sigmoidoscopy Performed\"\n            or exists \"Fecal Immunochemical Test DNA Performed\"\n            or exists \"CT Colonography Performed\""
          }, {
            "url": "displaySequence",
            "valueInteger": 7
          } ]
        }, {
          "url": "http://hl7.org/fhir/us/cqfmeasures/StructureDefinition/cqfm-logicDefinition",
          "extension": [ {
            "url": "libraryName",
            "valueString": "AdultOutpatientEncountersFHIR4"
          }, {
            "url": "name",
            "valueString": "Qualifying Encounters"
          }, {
            "url": "statement",
            "valueString": "define \"Qualifying Encounters\":\n  (\n                    [Encounter: \"Office Visit\"]\n                  \t\tunion [Encounter: \"Annual Wellness Visit\"]\n                  \t\tunion [Encounter: \"Preventive Care Services - Established Office Visit, 18 and Up\"]\n                  \t\tunion [Encounter: \"Preventive Care Services-Initial Office Visit, 18 and Up\"]\n                  \t\tunion [Encounter: \"Home Healthcare Services\"]\n                  ) ValidEncounter\n                \t\twhere ValidEncounter.status  = 'finished'\n                \t\tand Global.\"Normalize Interval\"(ValidEncounter.period) during \"Measurement Period\""
          }, {
            "url": "displaySequence",
            "valueInteger": 8
          } ]
        }, {
          "url": "http://hl7.org/fhir/us/cqfmeasures/StructureDefinition/cqfm-logicDefinition",
          "extension": [ {
            "url": "libraryName",
            "valueString": "ColorectalCancerScreeningsFHIR"
          }, {
            "url": "name",
            "valueString": "Telehealth Services"
          }, {
            "url": "statement",
            "valueString": "define \"Telehealth Services\":\n  ( [Encounter: \"Online Assessments\"]\n            union [Encounter: \"Telephone Visits\"] ) TelehealthEncounter\n            where TelehealthEncounter.status = 'finished'\n              and Global.\"Normalize Interval\" ( TelehealthEncounter.period ) during \"Measurement Period\""
          }, {
            "url": "displaySequence",
            "valueInteger": 9
          } ]
        }, {
          "url": "http://hl7.org/fhir/us/cqfmeasures/StructureDefinition/cqfm-logicDefinition",
          "extension": [ {
            "url": "libraryName",
            "valueString": "ColorectalCancerScreeningsFHIR"
          }, {
            "url": "name",
            "valueString": "Initial Population"
          }, {
            "url": "statement",
            "valueString": "define \"Initial Population\":\n  AgeInYearsAt(date from start of \"Measurement Period\") in Interval[50, 75 )\n            and exists ( AdultOutpatientEncounters.\"Qualifying Encounters\"\n                union \"Telehealth Services\"\n            )"
          }, {
            "url": "displaySequence",
            "valueInteger": 10
          } ]
        }, {
          "url": "http://hl7.org/fhir/us/cqfmeasures/StructureDefinition/cqfm-logicDefinition",
          "extension": [ {
            "url": "libraryName",
            "valueString": "ColorectalCancerScreeningsFHIR"
          }, {
            "url": "name",
            "valueString": "Denominator"
          }, {
            "url": "statement",
            "valueString": "define \"Denominator\":\n  \"Initial Population\""
          }, {
            "url": "displaySequence",
            "valueInteger": 11
          } ]
        }, {
          "url": "http://hl7.org/fhir/us/cqfmeasures/StructureDefinition/cqfm-logicDefinition",
          "extension": [ {
            "url": "libraryName",
            "valueString": "SupplementalDataElementsFHIR4"
          }, {
            "url": "name",
            "valueString": "SDE Payer"
          }, {
            "url": "statement",
            "valueString": "define \"SDE Payer\":\n  [Coverage: type in \"Payer\"] Payer\n        return {\n          code: Payer.type,\n          period: Payer.period\n        }"
          }, {
            "url": "displaySequence",
            "valueInteger": 12
          } ]
        }, {
          "url": "http://hl7.org/fhir/us/cqfmeasures/StructureDefinition/cqfm-logicDefinition",
          "extension": [ {
            "url": "libraryName",
            "valueString": "ColorectalCancerScreeningsFHIR"
          }, {
            "url": "name",
            "valueString": "SDE Payer"
          }, {
            "url": "statement",
            "valueString": "define \"SDE Payer\":\n  SDE.\"SDE Payer\""
          }, {
            "url": "displaySequence",
            "valueInteger": 13
          } ]
        }, {
          "url": "http://hl7.org/fhir/us/cqfmeasures/StructureDefinition/cqfm-logicDefinition",
          "extension": [ {
            "url": "libraryName",
            "valueString": "SupplementalDataElementsFHIR4"
          }, {
            "url": "name",
            "valueString": "SDE Ethnicity"
          }, {
            "url": "statement",
            "valueString": "define \"SDE Ethnicity\":\n  (flatten (\n      Patient.extension Extension\n        where Extension.url = 'http://hl7.org/fhir/us/core/StructureDefinition/us-core-ethnicity'\n          return Extension.extension\n    )) E\n      where E.url = 'ombCategory'\n        or E.url = 'detailed'\n      return E.value as Coding"
          }, {
            "url": "displaySequence",
            "valueInteger": 14
          } ]
        }, {
          "url": "http://hl7.org/fhir/us/cqfmeasures/StructureDefinition/cqfm-logicDefinition",
          "extension": [ {
            "url": "libraryName",
            "valueString": "ColorectalCancerScreeningsFHIR"
          }, {
            "url": "name",
            "valueString": "SDE Ethnicity"
          }, {
            "url": "statement",
            "valueString": "define \"SDE Ethnicity\":\n  SDE.\"SDE Ethnicity\""
          }, {
            "url": "displaySequence",
            "valueInteger": 15
          } ]
        }, {
          "url": "http://hl7.org/fhir/us/cqfmeasures/StructureDefinition/cqfm-logicDefinition",
          "extension": [ {
            "url": "libraryName",
            "valueString": "HospiceFHIR4"
          }, {
            "url": "name",
            "valueString": "Has Hospice"
          }, {
            "url": "statement",
            "valueString": "define \"Has Hospice\":\n  exists (\n                [Encounter: \"Encounter Inpatient\"] DischargeHospice\n            \t\t\twhere DischargeHospice.status = 'finished'\n            \t\t    and (\n            \t        DischargeHospice.hospitalization.dischargeDisposition ~ \"Discharge to home for hospice care (procedure)\"\n            \t\t\t\t    or DischargeHospice.hospitalization.dischargeDisposition ~ \"Discharge to healthcare facility for hospice care (procedure)\"\n            \t    \t)\n            \t\t\t\tand Global.\"Normalize Interval\"(DischargeHospice.period) ends during \"Measurement Period\"\n            \t)\n                or exists (\n                  [ServiceRequest: \"Hospice care ambulatory\"] HospiceOrder\n                    where HospiceOrder.status in {'active', 'completed'} \n                    and HospiceOrder.intent = 'order'\n                        and Global.\"Normalize Interval\"(HospiceOrder.authoredOn) during \"Measurement Period\"\n                )\n                or exists (\n                  [Procedure: \"Hospice care ambulatory\"] HospicePerformed\n                    where HospicePerformed.status = 'completed'\n                      and Global.\"Normalize Interval\"(HospicePerformed.performed) overlaps \"Measurement Period\"\n                )"
          }, {
            "url": "displaySequence",
            "valueInteger": 16
          } ]
        }, {
          "url": "http://hl7.org/fhir/us/cqfmeasures/StructureDefinition/cqfm-logicDefinition",
          "extension": [ {
            "url": "libraryName",
            "valueString": "ColorectalCancerScreeningsFHIR"
          }, {
            "url": "name",
            "valueString": "Malignant Neoplasm"
          }, {
            "url": "statement",
            "valueString": "define \"Malignant Neoplasm\":\n  [Condition: \"Malignant Neoplasm of Colon\"] ColorectalCancer\n            where Global.\"Prevalence Period\" ( ColorectalCancer ) starts on or before \n              end of \"Measurement Period\""
          }, {
            "url": "displaySequence",
            "valueInteger": 17
          } ]
        }, {
          "url": "http://hl7.org/fhir/us/cqfmeasures/StructureDefinition/cqfm-logicDefinition",
          "extension": [ {
            "url": "libraryName",
            "valueString": "ColorectalCancerScreeningsFHIR"
          }, {
            "url": "name",
            "valueString": "Total Colectomy Performed"
          }, {
            "url": "statement",
            "valueString": "define \"Total Colectomy Performed\":\n  [Procedure: \"Total Colectomy\"] Colectomy\n            where Colectomy.status = 'completed'\n              and Global.\"Normalize Interval\" ( Colectomy.performed ) ends on or before \n              end of \"Measurement Period\""
          }, {
            "url": "displaySequence",
            "valueInteger": 18
          } ]
        }, {
          "url": "http://hl7.org/fhir/us/cqfmeasures/StructureDefinition/cqfm-logicDefinition",
          "extension": [ {
            "url": "libraryName",
            "valueString": "AdvancedIllnessandFrailtyExclusionECQMFHIR4"
          }, {
            "url": "name",
            "valueString": "Has Criteria Indicating Frailty"
          }, {
            "url": "statement",
            "valueString": "define \"Has Criteria Indicating Frailty\":\n  exists ( [DeviceRequest: \"Frailty Device\"] FrailtyDeviceOrder\n                where FrailtyDeviceOrder.status in { 'active', 'on-hold', 'completed' }\n                  and FrailtyDeviceOrder.intent = 'order'\n                  and Global.\"Normalize Interval\" ( FrailtyDeviceOrder.authoredOn ) during \"Measurement Period\"\n            )\n              or exists ( [Observation: \"Frailty Device\"] FrailtyDeviceApplied\n                  where FrailtyDeviceApplied.status in { 'final', 'amended', 'corrected' }\n                    and Global.\"Normalize Interval\" ( FrailtyDeviceApplied.effective ) overlaps \"Measurement Period\"\n              )\n           or exists  ( [Condition: \"Frailty Diagnosis\"] FrailtyDiagnosis\n                where Global.\"Prevalence Period\" ( FrailtyDiagnosis ) overlaps \"Measurement Period\"\n            )\n              or exists ( [Encounter: \"Frailty Encounter\"] FrailtyEncounter\n                  where FrailtyEncounter.status = 'finished'\n                    and Global.\"Normalize Interval\" ( FrailtyEncounter.period ) overlaps \"Measurement Period\"\n              )\n              or exists ( [Observation: \"Frailty Symptom\"] FrailtySymptom\n                  where FrailtySymptom.status in { 'preliminary', 'final', 'amended', 'corrected' }\n                    and Global.\"Normalize Interval\" ( FrailtySymptom.effective ) overlaps \"Measurement Period\"\n              )"
          }, {
            "url": "displaySequence",
            "valueInteger": 19
          } ]
        }, {
          "url": "http://hl7.org/fhir/us/cqfmeasures/StructureDefinition/cqfm-logicDefinition",
          "extension": [ {
            "url": "libraryName",
            "valueString": "AdvancedIllnessandFrailtyExclusionECQMFHIR4"
          }, {
            "url": "name",
            "valueString": "Outpatient Encounters with Advanced Illness"
          }, {
            "url": "statement",
            "valueString": "define \"Outpatient Encounters with Advanced Illness\":\n  ( ( [Encounter: \"Outpatient\"]\n                union [Encounter: \"Observation\"]\n                union [Encounter: \"Emergency Department Visit\"]\n                union [Encounter: \"Nonacute Inpatient\"] ) Outpatient\n                where Outpatient.status = 'finished' ) OutpatientEncounter\n                with [Condition: \"Advanced Illness\"] AdvancedIllnessDiagnosis\n                  such that AdvancedIllnessDiagnosis in Global.EncounterDiagnosis ( OutpatientEncounter )\n                    and Global.\"Normalize Interval\" ( OutpatientEncounter.period ) starts 2 years or less on or before \n                    end of \"Measurement Period\""
          }, {
            "url": "displaySequence",
            "valueInteger": 20
          } ]
        }, {
          "url": "http://hl7.org/fhir/us/cqfmeasures/StructureDefinition/cqfm-logicDefinition",
          "extension": [ {
            "url": "libraryName",
            "valueString": "AdvancedIllnessandFrailtyExclusionECQMFHIR4"
          }, {
            "url": "name",
            "valueString": "Two Outpatient Encounters with Advanced Illness on Different Dates of Service"
          }, {
            "url": "statement",
            "valueString": "define \"Two Outpatient Encounters with Advanced Illness on Different Dates of Service\":\n  from\n                \"Outpatient Encounters with Advanced Illness\" OutpatientEncounter1,\n                \"Outpatient Encounters with Advanced Illness\" OutpatientEncounter2\n                where OutpatientEncounter2.period ends 1 day or more after day of \n                end of OutpatientEncounter1.period\n                return OutpatientEncounter1"
          }, {
            "url": "displaySequence",
            "valueInteger": 21
          } ]
        }, {
          "url": "http://hl7.org/fhir/us/cqfmeasures/StructureDefinition/cqfm-logicDefinition",
          "extension": [ {
            "url": "libraryName",
            "valueString": "AdvancedIllnessandFrailtyExclusionECQMFHIR4"
          }, {
            "url": "name",
            "valueString": "Inpatient Encounter with Advanced Illness"
          }, {
            "url": "statement",
            "valueString": "define \"Inpatient Encounter with Advanced Illness\":\n  ( [Encounter: \"Acute Inpatient\"] AcuteInpatient\n                where AcuteInpatient.status = 'finished' ) InpatientEncounter\n                with [Condition: \"Advanced Illness\"] AdvancedIllnessDiagnosis\n                  such that AdvancedIllnessDiagnosis in Global.EncounterDiagnosis ( InpatientEncounter )\n                    and Global.\"Normalize Interval\" ( InpatientEncounter.period ) starts 2 years or less on or before \n                    end of \"Measurement Period\""
          }, {
            "url": "displaySequence",
            "valueInteger": 22
          } ]
        }, {
          "url": "http://hl7.org/fhir/us/cqfmeasures/StructureDefinition/cqfm-logicDefinition",
          "extension": [ {
            "url": "libraryName",
            "valueString": "AdvancedIllnessandFrailtyExclusionECQMFHIR4"
          }, {
            "url": "name",
            "valueString": "Dementia Medications In Year Before or During Measurement Period"
          }, {
            "url": "statement",
            "valueString": "define \"Dementia Medications In Year Before or During Measurement Period\":\n  [MedicationRequest: \"Dementia Medications\"] DementiaMed\n                where DementiaMed.status = 'active'\n                  and DementiaMed.intent = 'order'\n                  and CMD.\"MedicationPeriod\"(DementiaMed)overlaps Interval[( start of \"Measurement Period\" - 1 year ), \n                  end of \"Measurement Period\"]"
          }, {
            "url": "displaySequence",
            "valueInteger": 23
          } ]
        }, {
          "url": "http://hl7.org/fhir/us/cqfmeasures/StructureDefinition/cqfm-logicDefinition",
          "extension": [ {
            "url": "libraryName",
            "valueString": "AdvancedIllnessandFrailtyExclusionECQMFHIR4"
          }, {
            "url": "name",
            "valueString": "Advanced Illness and Frailty Exclusion Not Including Over Age 80"
          }, {
            "url": "statement",
            "valueString": "define \"Advanced Illness and Frailty Exclusion Not Including Over Age 80\":\n  AgeInYearsAt(date from start of \"Measurement Period\")>= 65\n                and \"Has Criteria Indicating Frailty\"\n                and ( exists \"Two Outpatient Encounters with Advanced Illness on Different Dates of Service\"\n                    or exists ( \"Inpatient Encounter with Advanced Illness\" )\n                    or exists \"Dementia Medications In Year Before or During Measurement Period\"\n                )"
          }, {
            "url": "displaySequence",
            "valueInteger": 24
          } ]
        }, {
          "url": "http://hl7.org/fhir/us/cqfmeasures/StructureDefinition/cqfm-logicDefinition",
          "extension": [ {
            "url": "libraryName",
            "valueString": "AdvancedIllnessandFrailtyExclusionECQMFHIR4"
          }, {
            "url": "name",
            "valueString": "Long Term Care Periods During Measurement Period"
          }, {
            "url": "statement",
            "valueString": "define \"Long Term Care Periods During Measurement Period\":\n  ( [Encounter: \"Care Services in Long-Term Residential Facility\"]\n                union [Encounter: \"Nursing Facility Visit\"] ) LongTermFacilityEncounter\n                where LongTermFacilityEncounter.status = 'finished'\n                  and Global.\"Normalize Interval\" ( LongTermFacilityEncounter.period ) overlaps \"Measurement Period\"\n                return Global.\"Normalize Interval\" ( LongTermFacilityEncounter.period )\n                  intersect \"Measurement Period\""
          }, {
            "url": "displaySequence",
            "valueInteger": 25
          } ]
        }, {
          "url": "http://hl7.org/fhir/us/cqfmeasures/StructureDefinition/cqfm-logicDefinition",
          "extension": [ {
            "url": "libraryName",
            "valueString": "AdvancedIllnessandFrailtyExclusionECQMFHIR4"
          }, {
            "url": "name",
            "valueString": "Long Term Care Overlapping Periods"
          }, {
            "url": "statement",
            "valueString": "define \"Long Term Care Overlapping Periods\":\n  collapse ( \"Long Term Care Periods During Measurement Period\" )"
          }, {
            "url": "displaySequence",
            "valueInteger": 26
          } ]
        }, {
          "url": "http://hl7.org/fhir/us/cqfmeasures/StructureDefinition/cqfm-logicDefinition",
          "extension": [ {
            "url": "libraryName",
            "valueString": "AdvancedIllnessandFrailtyExclusionECQMFHIR4"
          }, {
            "url": "name",
            "valueString": "Long Term Care Adjacent Periods"
          }, {
            "url": "statement",
            "valueString": "define \"Long Term Care Adjacent Periods\":\n  from\n                \"Long Term Care Overlapping Periods\" LTCPeriod1,\n                \"Long Term Care Overlapping Periods\" LTCPeriod2\n                where \n                end of LTCPeriod1 within 1 day of start of LTCPeriod2\n                return Interval[start of LTCPeriod1, \n                end of LTCPeriod2]"
          }, {
            "url": "displaySequence",
            "valueInteger": 27
          } ]
        }, {
          "url": "http://hl7.org/fhir/us/cqfmeasures/StructureDefinition/cqfm-logicDefinition",
          "extension": [ {
            "url": "libraryName",
            "valueString": "AdvancedIllnessandFrailtyExclusionECQMFHIR4"
          }, {
            "url": "name",
            "valueString": "Max Long Term Care Period Length"
          }, {
            "url": "statement",
            "valueString": "define \"Max Long Term Care Period Length\":\n  Max((collapse(\"Long Term Care Overlapping Periods\"\n                    union \"Long Term Care Adjacent Periods\"\n                ))LTCPeriods\n                  return duration in days of LTCPeriods\n              )"
          }, {
            "url": "displaySequence",
            "valueInteger": 28
          } ]
        }, {
          "url": "http://hl7.org/fhir/us/cqfmeasures/StructureDefinition/cqfm-logicDefinition",
          "extension": [ {
            "url": "libraryName",
            "valueString": "AdvancedIllnessandFrailtyExclusionECQMFHIR4"
          }, {
            "url": "name",
            "valueString": "Has Long Term Care Periods Longer Than 90 Consecutive Days"
          }, {
            "url": "statement",
            "valueString": "define \"Has Long Term Care Periods Longer Than 90 Consecutive Days\":\n  \"Max Long Term Care Period Length\" > 90"
          }, {
            "url": "displaySequence",
            "valueInteger": 29
          } ]
        }, {
          "url": "http://hl7.org/fhir/us/cqfmeasures/StructureDefinition/cqfm-logicDefinition",
          "extension": [ {
            "url": "libraryName",
            "valueString": "PalliativeCareFHIR"
          }, {
            "url": "name",
            "valueString": "Palliative Care in the Measurement Period"
          }, {
            "url": "statement",
            "valueString": "define \"Palliative Care in the Measurement Period\":\n  exists ( [Observation: \"Functional Assessment of Chronic Illness Therapy - Palliative Care Questionnaire (FACIT-Pal)\"] PalliativeAssessment\n              where PalliativeAssessment.status in { 'final', 'amended', 'corrected' }\n                and exists ( PalliativeAssessment.category PalliativeAssessmentCategory\n                    where \"survey\" in FHIRHelpers.ToConcept ( PalliativeAssessmentCategory ).codes\n                )\n                and Global.\"Normalize Interval\" ( PalliativeAssessment.effective ) overlaps \"Measurement Period\"\n          )\n            or exists ( [Encounter: \"Palliative Care Encounter\"] PalliativeEncounter\n                where PalliativeEncounter.status = 'finished'\n                  and Global.\"Normalize Interval\" ( PalliativeEncounter.period ) overlaps \"Measurement Period\"\n            )\n            or exists ( [Procedure: \"Palliative Care Intervention\"] PalliativeIntervention\n                where PalliativeIntervention.status in { 'completed', 'in-progress' }\n                  and Global.\"Normalize Interval\" ( PalliativeIntervention.performed ) overlaps \"Measurement Period\"\n            )"
          }, {
            "url": "displaySequence",
            "valueInteger": 30
          } ]
        }, {
          "url": "http://hl7.org/fhir/us/cqfmeasures/StructureDefinition/cqfm-logicDefinition",
          "extension": [ {
            "url": "libraryName",
            "valueString": "ColorectalCancerScreeningsFHIR"
          }, {
            "url": "name",
            "valueString": "Denominator Exclusions"
          }, {
            "url": "statement",
            "valueString": "define \"Denominator Exclusions\":\n  Hospice.\"Has Hospice\"\n            or exists \"Malignant Neoplasm\"\n            or exists \"Total Colectomy Performed\"\n            or FrailtyLTI.\"Advanced Illness and Frailty Exclusion Not Including Over Age 80\"\n            or ( AgeInYearsAt(date from start of \"Measurement Period\")>= 65\n                and FrailtyLTI.\"Has Long Term Care Periods Longer Than 90 Consecutive Days\"\n            )\n            or PalliativeCare.\"Palliative Care in the Measurement Period\""
          }, {
            "url": "displaySequence",
            "valueInteger": 31
          } ]
        }, {
          "url": "http://hl7.org/fhir/us/cqfmeasures/StructureDefinition/cqfm-logicDefinition",
          "extension": [ {
            "url": "libraryName",
            "valueString": "SupplementalDataElementsFHIR4"
          }, {
            "url": "name",
            "valueString": "SDE Race"
          }, {
            "url": "statement",
            "valueString": "define \"SDE Race\":\n  (flatten (\n      Patient.extension Extension\n        where Extension.url = 'http://hl7.org/fhir/us/core/StructureDefinition/us-core-race'\n          return Extension.extension\n    )) E\n      where E.url = 'ombCategory'\n        or E.url = 'detailed'\n      return E.value as Coding"
          }, {
            "url": "displaySequence",
            "valueInteger": 32
          } ]
        }, {
          "url": "http://hl7.org/fhir/us/cqfmeasures/StructureDefinition/cqfm-logicDefinition",
          "extension": [ {
            "url": "libraryName",
            "valueString": "ColorectalCancerScreeningsFHIR"
          }, {
            "url": "name",
            "valueString": "SDE Race"
          }, {
            "url": "statement",
            "valueString": "define \"SDE Race\":\n  SDE.\"SDE Race\""
          }, {
            "url": "displaySequence",
            "valueInteger": 33
          } ]
        } ],
